Script:
TopNav = {
    init: function(app, container, page) {
        app = app || session.app;
        container = container || $(".component[name=TopNav]");
        page = page || session.page;
        var query = "ContentManagement/Page?$filter=AppId eq " + app.Id + " and ParentId eq null and ShowOnMenus eq true&$orderby=Order asc&$expand=PageInfo,Pages($filter=ShowOnMenus eq true;$orderby=Order asc;$expand=PageInfo,Pages($filter=ShowOnMenus eq true;$orderby=Order asc;$expand=PageInfo))";
        api.get(query).then(function(pages) {
            var menu = $("ul[name=menu]", container);
            menu.empty();
            TopNav.generateNavMenu(menu, TopNav.orderedVisiblePages(pages.value || []));
        });
    },

    generateNavMenu: function(nav, pages) {
        for(var i = 0; i < pages.length; i++) {
            var page = pages[i];
            var visibleChildren = TopNav.orderedVisiblePages(page.Pages || []);

            if(visibleChildren.length > 0)
                TopNav.generateNavDropdown(nav, page, visibleChildren);
            else
                TopNav.generateNavItem(nav, page, false);
        }
    },

    generateNavItem: function(nav, page, dropdown) {
        var navItem = $('<li class="' + TopNav.itemClass(page, dropdown) + '"></li>');
        navItem.append($('<a href="/' + TopNav.pathOf(page) + '" class="' + TopNav.linkClass(page, dropdown) + '">' + TopNav.titleOf(page) + '</a>'));
        nav.append(navItem);
    },

    generateNavDropdown: function(nav, page, children) {
        var navItem = $('<li class="' + TopNav.itemClass(page, true) + '"></li>');
        navItem.append($('<a href="/' + TopNav.pathOf(page) + '" class="nav-link dropdown-toggle ' + (TopNav.isCurrentPage(page, true) ? 'active' : '') +'" aria-expanded="false">' + TopNav.titleOf(page) + '</a>'));
        var dropdown = $('<ul class="submenu dropdown-menu"></ul>');
        for(var i = 0; i < children.length; i++) {
            TopNav.generateNavDropdownItem(dropdown, children[i]);
        }
        navItem.append(dropdown);
        nav.append(navItem);
    },

    generateNavDropdownItem: function(dropdown, page) {
        var visibleChildren = TopNav.orderedVisiblePages(page.Pages || []);
        var navItem = $('<li class="' + (visibleChildren.length > 0 ? 'dropdown' : '') + '"></li>');
        navItem.append($('<a href="/' + TopNav.pathOf(page) + '" class="' + TopNav.linkClass(page, true) + '">' + TopNav.titleOf(page) + '</a>'));
        if(visibleChildren.length > 0) {
            var submenu = $('<ul class="submenu dropdown-menu"></ul>');
            for(var i = 0; i < visibleChildren.length; i++) {
                TopNav.generateNavDropdownItem(submenu, visibleChildren[i]);
            }
            navItem.append(submenu);
        }
        dropdown.append(navItem);
    },

    orderedVisiblePages: function(pages) {
        return pages
            .filter(function(page) { return page && page.ShowOnMenus === true; })
            .sort(function(left, right) { return (left.Order || 0) - (right.Order || 0); });
    },

    pathOf: function(page) {
        return page.Path || '';
    },

    titleOf: function(page) {
        if(!page.PageInfo || page.PageInfo.length === 0)
            return page.Name;

        var culture = ($("html").attr("lang")) ? $("html").attr("lang") : "";
        var matchingPageInfos = page.PageInfo.filter(function(pi){
            return pi.CultureId == culture;
        });

        if(matchingPageInfos.length > 0)
            return matchingPageInfos[0].Title;

        var defaultPageInfo = page.PageInfo.filter(function(pi){
            return pi.CultureId == "";
        })[0];

        return defaultPageInfo ? defaultPageInfo.Title : page.Name;
    },

    itemClass: function(page, dropdown) {
        var isCurrentPage = TopNav.isCurrentPage(page, false);

        if(dropdown == true)
            return isCurrentPage
                ? 'nav-item dropdown active'
                : 'nav-item dropdown';
        return isCurrentPage
            ? 'nav-item active'
            : 'nav-item';
    },

    linkClass: function(page, dropdown) {
        var isCurrentPage = TopNav.isCurrentPage(page, false);
        if(dropdown == true)
            return isCurrentPage ? 'dropdown-item active' : 'dropdown-item';
        return isCurrentPage ? 'nav-link active' : 'nav-link';
    },

    isCurrentPage: function(page, isParent) {
        var currentPath = (session.page && session.page.Path) ? session.page.Path : '';
        var pagePath = page.Path || '';

        if(isParent == true)
            return pagePath !== '' && currentPath.indexOf(pagePath + '/') === 0;

        return currentPath === pagePath;
    }
};
